import os
import subprocess
import sys

# Ensure output dir exists
os.makedirs('/app/output', exist_ok=True)
os.makedirs('/tmp/poster', exist_ok=True)

latex_content = r"""\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usetikzlibrary{shapes.geometric, arrows, positioning, fit, backgrounds, shadows}
\pagestyle{empty}

% Deep navy / charcoal theme for S&P
\definecolor{primary}{HTML}{0B1121}
\definecolor{secondary}{HTML}{1E293B}
\definecolor{accent}{HTML}{06B6D4}
\definecolor{accentbg}{HTML}{0B3547}
\definecolor{bgposter}{HTML}{0F172A}
\definecolor{cardbg}{HTML}{1E293B}
\definecolor{titlebg}{HTML}{0B1121}
\definecolor{textlight}{HTML}{F8FAFC}
\definecolor{textgray}{HTML}{94A3B8}
\definecolor{stathighlight}{HTML}{1E293B}

\pagecolor{bgposter}
\color{textlight}

\setlist[itemize]{leftmargin=24pt, itemsep=10pt, parsep=6pt, topsep=6pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=10pt, parsep=6pt, topsep=6pt,
  label={\color{accent}\bfseries\arabic*.}}

\tcbset{
  darkcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{accent},
    left=20pt, right=16pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{34}{42}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=accentbg, coltext=textlight,
    toptitle=14pt, bottomtitle=14pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.3, color=black},
  },
  statcard/.style={
    enhanced, colback=cardbg, boxrule=2pt, colframe=accent, arc=8pt,
    left=16pt, right=16pt, top=16pt, bottom=16pt,
    valign=center, halign=center, coltext=textlight,
    drop shadow={opacity=0.3, color=black},
  }
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=6mm}
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=16pt, bottom=16pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4, color=black}
]{name=title, column=1, span=2, between=top and row2}{
  {\fontsize{64}{76}\selectfont\bfseries Bot Mitigation at Scale:}\\[16pt]
  {\fontsize{48}{60}\selectfont\bfseries Protecting Scientific Publishing Platforms}\\[16pt]
  {\fontsize{28}{36}\selectfont\color{accent} IEEE Symposium on Security and Privacy (S\&P) | \color{textgray} Case Study: www.science.org}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=bgposter, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=10pt, bottom=10pt,
  valign=center
]{name=stats, column=1, span=2, between=row2 and row4}{
  \centering
  \begin{minipage}[c]{0.45\linewidth}\centering
    \begin{tcolorbox}[statcard]
      {\fontsize{76}{88}\selectfont\bfseries\color{accent} 85\%}\\[10pt]
      {\fontsize{28}{36}\selectfont\color{textlight} Reduction in Unauthorized Scraping}
    \end{tcolorbox}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.45\linewidth}\centering
    \begin{tcolorbox}[statcard]
      {\fontsize{76}{88}\selectfont\bfseries\color{accent} 99.97\%}\\[10pt]
      {\fontsize{28}{36}\selectfont\color{textlight} Uptime During Bot Surge Events}
    \end{tcolorbox}
  \end{minipage}
}

% ══ LEFT COLUMN ══

\posterbox[darkcard, title={The Bot Threat Landscape}
]{name=threat, column=1, between=row4 and row8}{
  \fontsize{26}{36}\selectfont
  Scientific publishing platforms host highly valuable intellectual property and DOIs, making them prime targets for automated threats:
  \vspace{16pt}
  \begin{itemize}
    \item \textbf{Attack Volume:} Approx. \colorbox{accentbg}{\textbf{\color{textlight} 47\% }} of internet traffic in 2024 was automated.
    \item \textbf{Malicious Share:} \colorbox{accentbg}{\textbf{\color{textlight} 30\% }} of total traffic consists of malicious bots scraping full-text articles.
    \item \textbf{DDoS Impacts:} Before mitigation, platforms sustained $\sim$1.2M scraping attempts per day, heavily taxing origin CPUs (78\% avg load).
  \end{itemize}
}

\posterbox[darkcard, title={Performance \& Security Outcomes}
]{name=outcomes, column=1, between=row8 and row15}{
  \fontsize{26}{36}\selectfont
  Deployment of CDN-level security services dramatically shifted the threat baseline:
  \vspace{20pt}

  \renewcommand{\arraystretch}{2.2}
  \begin{tabular}{p{0.55\linewidth} | p{0.35\linewidth}}
    \rowcolor{accentbg}
    \textbf{\color{textlight}Metric} & \textbf{\color{textlight}Result} \\
    \rowcolor{primary!50}
    Scraping attempts / day & \textbf{\color{accent}$\downarrow$ from 1.2M to 180k} \\
    \rowcolor{cardbg}
    Origin server CPU load & \textbf{\color{accent}$\downarrow$ 78\% to 42\%} \\
    \rowcolor{primary!50}
    Verified user friction & \textbf{\color{accent}< 0.3\% reported} \\
    \rowcolor{cardbg}
    Verification latency & \textbf{\color{accent}< 2 seconds} \\
    \rowcolor{primary!50}
    Page-load overhead & \textbf{\color{accent}< 150 ms} \\
  \end{tabular}

  \vspace{24pt}
  \textbf{Conclusion:} By absorbing automated traffic at the edge, origin servers remain responsive even under 10$\times$ normal surge events.
}

\posterbox[darkcard, title={Key Takeaways}
]{name=takeaways, column=1, between=row15 and bottom}{
  \fontsize{26}{36}\selectfont
  \begin{enumerate}
    \item \textbf{Ubiquity:} Nearly half of requests are bots. Mitigation is not optional for academic publishers.
    \item \textbf{Efficacy:} Multi-stage pipelines block the vast majority of threats with negligible human impact.
    \item \textbf{Observability:} Traceable identifiers ensure optimal tuning between security and UX.
    \item \textbf{Partnership:} CDN providers and publishers must collaborate to sustain open knowledge access.
  \end{enumerate}
}

% ══ RIGHT COLUMN ══

\posterbox[darkcard, title={Challenge-Based Verification Pipeline}
]{name=pipeline, column=2, between=row4 and row15}{
  \fontsize{24}{34}\selectfont
  Multi-stage CDN edge mitigation processes intercept and validate requests before they hit origin infrastructure:

  \vspace{30pt}
  \centering
  \begin{tikzpicture}[
      node distance=1.6cm,
      every node/.style={text=textlight, font=\fontsize{24}{32}\selectfont},
      box/.style={rectangle, draw=accent, thick, fill=bgposter, align=center, minimum width=10cm, minimum height=1.6cm, drop shadow={opacity=0.3, color=black}},
      arrow/.style={thick,->,>=stealth, draw=accent, line width=1.5pt}
    ]
    \node (user) [box, fill=primary, text=textlight] {\textbf{1. Request Interception}\\ \small{CDN edge node (<50ms)}};
    \node (score) [box, below=of user] {\textbf{2. Threat Scoring}\\ \small{IP rep., TLS fingerprint ($\sim$100ms)}};
    \node (challenge) [box, below=of score] {\textbf{3. Challenge Issuance}\\ \small{JS / CAPTCHA challenge ($\sim$500ms)}};
    \node (verify) [box, below=of challenge] {\textbf{4. Verification Check}\\ \small{Validate response \& Ray ID ($\sim$200ms)}};
    \node (grant) [box, fill=accentbg, draw=accent, below=of verify] {\textbf{5. Access Grant}\\ \small{Forward with session token (<50ms)}};

    \draw [arrow] (user) -- (score);
    \draw [arrow] (score) -- (challenge) node[midway, right, text=textgray, xshift=10pt] {Risk > Threshold};
    \draw [arrow] (challenge) -- (verify);
    \draw [arrow] (verify) -- (grant) node[midway, right, text=textgray, xshift=10pt] {Success};

    % Bypass arrows
    \draw [arrow, dashed, draw=textgray, line width=1pt] (score.east) -- ++(1.5,0) |- (grant.east) node[near start, right, text=textgray, xshift=5pt] {Low Risk (Bypass)};

    % Block arrow
    \draw [arrow, draw=red!60, line width=1pt] (verify.west) -- ++(-1.5,0) node[midway, above, text=red!60, yshift=5pt] {Fail} |- (challenge.west);
  \end{tikzpicture}
  \vspace{30pt}

  \raggedright
  Total human latency is typically \colorbox{accentbg}{\textbf{\color{textlight} under 2 seconds}}, while bots lacking JS execution are blocked at step 3.
}

\posterbox[darkcard, title={Usability vs. Security Trade-offs}
]{name=tradeoffs, column=2, between=row15 and bottom}{
  \fontsize{26}{36}\selectfont
  Security measures must avoid excluding legitimate academic access:
  \vspace{16pt}
  \begin{itemize}
    \item \textbf{Accessibility:} Challenge pages adhere to WCAG 2.1 standards for users with disabilities.
    \item \textbf{Institutional Access:} Allowlisting university IP ranges prevents unnecessary friction for campus networks.
    \item \textbf{Transparency:} Displaying clear messaging (\textit{"Performing security verification..."}) reduces bounce rates.
    \item \textbf{Privacy:} The pipeline balances granular threat telemetry against data minimization principles.
  \end{itemize}
}

\end{tcbposter}
\end{document}
"""

with open('/tmp/poster/main.tex', 'w', encoding='utf-8') as f:
    f.write(latex_content)

print("Starting pdflatex compilation...")
proc = subprocess.run(['pdflatex', '-interaction=nonstopmode', 'main.tex'], cwd='/tmp/poster', capture_output=True, text=True)
if proc.returncode != 0:
    print("PDFLaTeX Error:")
    print(proc.stdout)
    sys.exit(1)

print("PDF generated successfully.")

# Install PyMuPDF
subprocess.run(['pip', 'install', 'pymupdf', '--break-system-packages'], check=False)
subprocess.run(['pip', 'install', 'pymupdf'], check=False)

import fitz
print("Converting PDF to PNG...")
doc = fitz.open('/tmp/poster/main.pdf')
page = doc[0]
pix = page.get_pixmap(dpi=300)
pix.save('/app/output/final_poster.png')
doc.close()
print("Poster successfully saved to /app/output/final_poster.png")
EOF
python3 /tmp/generate_poster.py
